.status-container {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  width: 100%;
}

.status-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  width: 215px;
  min-width: 100px;
  background-color: white;
  border-radius: 8px;
  padding: 12px 12px;
  text-align: left;
  cursor: pointer;
  border: 2px solid transparent;
  transition: border-color 0.3s;
}

.status-card.active {
  border-color: #1068EB; /* blue border for selected */
  background-color: #E8F0FD;
}

.status-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 14px;
  font-weight: 600;
  padding: 4px 8px;
  border-radius: 9999px;
  width: max-content;
}

/* Status colors: text + background */
.all-requests .status-label {
  color: #1068EB;
  background-color: #1068EB1A;
}
.draft .status-label {
  color: #4E32A2;
  background-color: #F1EDFD;
}
.pending-approval .status-label {
  color: #AC6F00;
  background-color: #FEF5E5;
}
.pending-assessment .status-label {
  color: #AC6F00;
  background-color: #FEF5E5;
}
.rejected-approver .status-label {
  color: #8C1D1D;
  background-color: #FAEAEA;
}
.rejected-assessor .status-label {
  color: #8C1D1D;
  background-color: #FAEAEA;
}
.completed .status-label {
  color: #267D36;
  background-color: #EBF7ED;
}
.cancelled .status-label {
  color: #272B30;
  background-color: #CED4DA;
}

.status-number {
  font-size: 20px;
  font-weight: bold;
  color: #101213;
  margin-top: 6px;
  text-align: left;
}


